{{openMooca}}\" aria-haspopup=\"dialog\" style=\"text-align:left;display:flex;flex-direction:column;gap:20px;min-height:300px;box-sizing:border-box;padding:32px;background:#FFFFFF;border:1px solid rgba(16,20,24,.08);border-radius:28px;cursor:pointer;color:#101418;font:inherit\">\n          <span style=\"display:flex;align-items:center;justify-content:space-between;gap:12px\">\n            <span style=\"width:56px;height:56px;border-radius:16px;background:#D8F0E6;color:#0B6B4D;display:flex;align-items:center;justify-content:center\">\n              <svg width=\"28\" height=\"28\" sc-camel-view-box=\"0 0 24 24\" aria-hidden=\"true\" style=\"fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round\"><path d=\"M22 7 13.5 15.5 8.5 10.5 2 17\"><\u002Fpath><path d=\"M16 7h6v6\"><\u002Fpath><\u002Fsvg>\n            <\u002Fspan>\n            <span style=\"font-size:13px;font-weight:600;padding:6px 12px;border-radius:999px;background:#D8F0E6;color:#0B6B4D\">4 Bidang<\u002Fspan>\n          <\u002Fspan>\n          <span class=\"display\" style=\"display:block;font-weight:600;font-size:28px;letter-spacing:-.02em\">Mooca Capital<\u002Fspan>\n          <span style=\"display:block;font-size:16px;line-height:1.6;color:#4A525C\">Pengembangan bisnis, investasi, kerja sama usaha, dan layanan asuransi untuk seluruh grup.<\u002Fspan>\n          <span style=\"margin-top:auto;display:flex;align-items:center;gap:8px;font-weight:600;font-size:15px;color:#0B6B4D\">\n            Lihat bidang usaha\n            <svg width=\"18\" height=\"18\" sc-camel-view-box=\"0 0 24 24\" aria-hidden=\"true\" style=\"fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round\"><path d=\"M5 12h14\"><\u002Fpath><path d=\"M12 5l7 7-7 7\"><\u002Fpath><\u002Fsvg>\n          <\u002Fspan>\n        <\u002Fbutton>\n\n        <button class=\"lift\" sc-camel-on-click=\"{{openLentera}}\" aria-haspopup=\"dialog\" style=\"text-align:left;display:flex;flex-direction:column;gap:20px;min-height:300px;box-sizing:border-box;padding:32px;background:#FFFFFF;border:1px solid rgba(16,20,24,.08);border-radius:28px;cursor:pointer;color:#101418;font:inherit\">\n          <span style=\"display:flex;align-items:center;justify-content:space-between;gap:12px\">\n            <span style=\"width:56px;height:56px;border-radius:16px;background:#FBEBCB;color:#8A5200;display:flex;align-items:center;justify-content:center\">\n              <svg width=\"28\" height=\"28\" sc-camel-view-box=\"0 0 24 24\" aria-hidden=\"true\" style=\"fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round\"><path d=\"M2 3h6a4 4 0 0 1 4 4v14a3 3 0 0 0-3-3H2z\"><\u002Fpath><path d=\"M22 3h-6a4 4 0 0 0-4 4v14a3 3 0 0 1 3-3h7z\"><\u002Fpath><\u002Fsvg>\n            <\u002Fspan>\n            <span style=\"font-size:13px;font-weight:600;padding:6px 12px;border-radius:999px;background:#FBEBCB;color:#8A5200\">3 Divisi<\u002Fspan>\n          <\u002Fspan>\n          <span class=\"display\" style=\"display:block;font-weight:600;font-size:28px;letter-spacing:-.02em\">Lentera Media<\u002Fspan>\n          <span style=\"display:block;font-size:16px;line-height:1.6;color:#4A525C\">Penerbitan, publikasi media, dan kerja sama media untuk klien maupun internal grup.<\u002Fspan>\n          <span style=\"margin-top:auto;display:flex;align-items:center;gap:8px;font-weight:600;font-size:15px;color:#8A5200\">\n            Lihat divisi\n            <svg width=\"18\" height=\"18\" sc-camel-view-box=\"0 0 24 24\" aria-hidden=\"true\" style=\"fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round\"><path d=\"M5 12h14\"><\u002Fpath><path d=\"M12 5l7 7-7 7\"><\u002Fpath><\u002Fsvg>\n          <\u002Fspan>\n        <\u002Fbutton>\n\n      <\u002Fdiv>\n    <\u002Fdiv>\n  <\u002Fsection>\n\n  <!-- ===== KONTAK + FOOTER ===== -->\n  <div style=\"background-color:#0E1217;background-image:radial-gradient(rgba(255,255,255,.07) 1px, transparent 1px);background-size:24px 24px\">\n    <section id=\"kontak\" style=\"max-width:1200px;margin:0 auto;padding:104px 24px;display:flex;flex-wrap:wrap;align-items:flex-start;gap:56px 80px\">\n      <div style=\"flex:1 1 380px;min-width:0;display:flex;flex-direction:column;gap:24px\">\n        <p style=\"margin:0;font-size:14px;letter-spacing:.16em;text-transform:uppercase;font-weight:600;color:{{accent}}\">Kontak<\u002Fp>\n        <h2 class=\"display\" style=\"margin:0;font-weight:700;font-size:clamp(30px,4vw,46px);line-height:1.1;letter-spacing:-.025em;color:#F6F4EF;text-wrap:balance\">Mari berbincang tentang kerja sama<\u002Fh2>\n        <p style=\"margin:0;font-size:18px;line-height:1.6;color:#B8BEC7;text-wrap:pretty\">Butuh layanan salah satu lini kami, atau tertarik menjajaki kerja sama usaha? Tulis pesan Anda, kami akan menanggapinya.<\u002Fp>\n        <div style=\"display:flex;flex-direction:column;gap:20px;margin-top:8px\">\n          <div style=\"display:flex;flex-direction:column;gap:4px\">\n            <span style=\"font-size:13px;letter-spacing:.12em;text-transform:uppercase;font-weight:600;color:#9AA3AE\">WhatsApp<\u002Fspan>\n            <span style=\"font-size:18px;color:#F6F4EF\">{{waDisplay}}<\u002Fspan>\n          <\u002Fdiv>\n          <div style=\"display:flex;flex-direction:column;gap:4px\">\n            <span style=\"font-size:13px;letter-spacing:.12em;text-transform:uppercase;font-weight:600;color:#9AA3AE\">Email<\u002Fspan>\n            <span style=\"font-size:18px;color:#F6F4EF\">[ALAMAT EMAIL]<\u002Fspan>\n          <\u002Fdiv>\n          <div style=\"display:flex;flex-direction:column;gap:4px\">\n            <span style=\"font-size:13px;letter-spacing:.12em;text-transform:uppercase;font-weight:600;color:#9AA3AE\">Alamat<\u002Fspan>\n            <span style=\"font-size:18px;color:#F6F4EF\">[ALAMAT KANTOR]<\u002Fspan>\n          <\u002Fdiv>\n        <\u002Fdiv>\n      <\u002Fdiv>\n\n      <div style=\"flex:1 1 420px;min-width:0;box-sizing:border-box;padding:32px;background:#FBFAF7;border-radius:28px;display:flex;flex-direction:column;gap:20px;color:#101418\">\n        <div style=\"display:flex;flex-direction:column;gap:8px\">\n          <label for=\"f-name\" style=\"font-size:15px;font-weight:600\">Nama<\u002Flabel>\n          <input id=\"f-name\" type=\"text\" autocomplete=\"name\" value=\"{{form.name}}\" sc-camel-on-change=\"{{setName}}\" style=\"width:100%;box-sizing:border-box;min-height:48px;padding:12px 14px;border:1px solid #8C877B;border-radius:12px;background:#FFFFFF;color:#101418;font-size:16px\">\n        <\u002Fdiv>\n        <div style=\"display:flex;flex-direction:column;gap:8px\">\n          <label for=\"f-topic\" style=\"font-size:15px;font-weight:600\">Lini usaha yang diminati<\u002Flabel>\n          <sc-raw-select id=\"f-topic\" value=\"{{form.topic}}\" sc-camel-on-change=\"{{setTopic}}\" style=\"width:100%;box-sizing:border-box;min-height:48px;padding:12px 14px;border:1px solid #8C877B;border-radius:12px;background:#FFFFFF;color:#101418;font-size:16px\">\n            <option value=\"Vallenca Lifestyle\">Vallenca Lifestyle<\u002Foption>\n            <option value=\"Vatech Corpora\">Vatech Corpora<\u002Foption>\n            <option value=\"Mooca Capital\">Mooca Capital<\u002Foption>\n            <option value=\"Lentera Media\">Lentera Media<\u002Foption>\n            <option value=\"Kerja sama lainnya\">Kerja sama lainnya<\u002Foption>\n          <\u002Fsc-raw-select>\n        <\u002Fdiv>\n        <div style=\"display:flex;flex-direction:column;gap:8px\">\n          <label for=\"f-msg\" style=\"font-size:15px;font-weight:600\">Pesan<\u002Flabel>\n          <textarea id=\"f-msg\" rows=\"4\" value=\"{{form.message}}\" sc-camel-on-change=\"{{setMessage}}\" style=\"width:100%;box-sizing:border-box;padding:12px 14px;border:1px solid #8C877B;border-radius:12px;background:#FFFFFF;color:#101418;font-size:16px;line-height:1.5;resize:vertical\"><\u002Ftextarea>\n        <\u002Fdiv>\n        <a class=\"btn\" href=\"{{waHref}}\" target=\"{{waTarget}}\" rel=\"noopener\" style=\"display:inline-flex;align-items:center;justify-content:center;gap:10px;min-height:52px;box-sizing:border-box;padding:14px 28px;border-radius:999px;background:#0E1217;color:#F6F4EF;font-weight:600;font-size:16px;text-decoration:none\">\n          Kirim via WhatsApp\n          <svg width=\"18\" height=\"18\" sc-camel-view-box=\"0 0 24 24\" aria-hidden=\"true\" style=\"fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round\"><path d=\"M5 12h14\"><\u002Fpath><path d=\"M12 5l7 7-7 7\"><\u002Fpath><\u002Fsvg>\n        <\u002Fa>\n      <\u002Fdiv>\n    <\u002Fsection>\n\n    <footer style=\"max-width:1200px;margin:0 auto;padding:28px 24px 40px;border-top:1px solid rgba(255,255,255,.12);display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:12px 24px\">\n      <p style=\"margin:0;font-size:14px;color:#9AA3AE\">© 2026 Ipin Entreprise Group. Hak cipta dilindungi.<\u002Fp>\n      <nav aria-label=\"Navigasi footer\" style=\"display:flex;flex-wrap:wrap;gap:0 24px\">\n        <a class=\"foot-link\" href=\"#tentang\" style=\"font-size:14px;padding:12px 0\">Tentang<\u002Fa>\n        <a class=\"foot-link\" href=\"#usaha\" style=\"font-size:14px;padding:12px 0\">Lini Usaha<\u002Fa>\n        <a class=\"foot-link\" href=\"#top\" style=\"font-size:14px;padding:12px 0\">Kembali ke atas<\u002Fa>\n      <\u002Fnav>\n    <\u002Ffooter>\n  <\u002Fdiv>\n\n  <!-- ===== POPUP DIVISI ===== -->\n  <sc-if value=\"{{isOpen}}\" hint-placeholder-val=\"{{ false }}\">\n    <div sc-camel-on-key-down=\"{{onKey}}\" style=\"position:fixed;inset:0;z-index:100;display:flex;align-items:center;justify-content:center;padding:16px;box-sizing:border-box\">\n      <button sc-camel-on-click=\"{{close}}\" aria-label=\"Tutup jendela\" style=\"position:absolute;inset:0;width:100%;height:100%;margin:0;padding:0;border:0;background:rgba(14,18,23,.62);cursor:default\"><\u002Fbutton>\n\n      <div role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"modal-title\" style=\"position:relative;width:100%;max-width:820px;max-height:calc(100vh - 32px);overflow-y:auto;background:#FBFAF7;border-radius:28px;box-shadow:0 30px 80px rgba(0,0,0,.35)\">\n\n        <div style=\"background:{{modal.tint}};padding:28px 32px;display:flex;align-items:flex-start;justify-content:space-between;gap:16px\">\n          <div style=\"display:flex;align-items:center;gap:20px;min-width:0\">\n            <div style=\"flex:none;width:64px;height:64px;border-radius:18px;background:#FFFFFF;color:{{modal.ink}};display:flex;align-items:center;justify-content:center\">\n              <sc-if value=\"{{isVallenca}}\" hint-placeholder-val=\"{{ false }}\">\n                <svg width=\"32\" height=\"32\" sc-camel-view-box=\"0 0 24 24\" aria-hidden=\"true\" style=\"fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round\"><path d=\"M20.38 3.46 16 2a4 4 0 0 1-8 0L3.62 3.46a2 2 0 0 0-1.34 2.23l.58 3.47a1 1 0 0 0 .99.84H6v10c0 1.1.9 2 2 2h8a2 2 0 0 0 2-2V10h2.15a1 1 0 0 0 .99-.84l.58-3.47a2 2 0 0 0-1.34-2.23z\"><\u002Fpath><\u002Fsvg>\n              <\u002Fsc-if>\n              <sc-if value=\"{{isVatech}}\" hint-placeholder-val=\"{{ false }}\">\n                <svg width=\"32\" height=\"32\" sc-camel-view-box=\"0 0 24 24\" aria-hidden=\"true\" style=\"fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round\"><path d=\"M13 2 3 14h9l-1 8 10-12h-9l1-8z\"><\u002Fpath><\u002Fsvg>\n              <\u002Fsc-if>\n              <sc-if value=\"{{isMooca}}\" hint-placeholder-val=\"{{ false }}\">\n                <svg width=\"32\" height=\"32\" sc-camel-view-box=\"0 0 24 24\" aria-hidden=\"true\" style=\"fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round\"><path d=\"M22 7 13.5 15.5 8.5 10.5 2 17\"><\u002Fpath><path d=\"M16 7h6v6\"><\u002Fpath><\u002Fsvg>\n              <\u002Fsc-if>\n              <sc-if value=\"{{isLentera}}\" hint-placeholder-val=\"{{ false }}\">\n                <svg width=\"32\" height=\"32\" sc-camel-view-box=\"0 0 24 24\" aria-hidden=\"true\" style=\"fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round\"><path d=\"M2 3h6a4 4 0 0 1 4 4v14a3 3 0 0 0-3-3H2z\"><\u002Fpath><path d=\"M22 3h-6a4 4 0 0 0-4 4v14a3 3 0 0 1 3-3h7z\"><\u002Fpath><\u002Fsvg>\n              <\u002Fsc-if>\n            <\u002Fdiv>\n            <div style=\"min-width:0\">\n              <p style=\"margin:0 0 4px;font-size:13px;font-weight:600;letter-spacing:.12em;text-transform:uppercase;color:{{modal.ink}}\">{{modal.eyebrow}}<\u002Fp>\n              <h3 id=\"modal-title\" class=\"display\" style=\"margin:0;font-weight:700;font-size:clamp(24px,4vw,34px);line-height:1.1;letter-spacing:-.02em;color:#101418\">{{modal.name}}<\u002Fh3>\n            <\u002Fdiv>\n          <\u002Fdiv>\n          <button id=\"modal-close\" sc-camel-on-click=\"{{close}}\" aria-label=\"Tutup\" style=\"flex:none;width:44px;height:44px;border-radius:999px;border:0;background:#FFFFFF;color:#101418;cursor:pointer;display:flex;align-items:center;justify-content:center\">\n            <svg width=\"20\" height=\"20\" sc-camel-view-box=\"0 0 24 24\" aria-hidden=\"true\" style=\"fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round\"><path d=\"M18 6 6 18\"><\u002Fpath><path d=\"M6 6l12 12\"><\u002Fpath><\u002Fsvg>\n          <\u002Fbutton>\n        <\u002Fdiv>\n\n        <div style=\"padding:32px;display:flex;flex-direction:column;gap:24px\">\n          <p style=\"margin:0;font-size:17px;line-height:1.6;color:#3A424C;text-wrap:pretty\">{{modal.tagline}}<\u002Fp>\n          <p style=\"margin:0;font-size:13px;font-weight:600;letter-spacing:.12em;text-transform:uppercase;color:#5A626C\">{{modal.listLabel}}<\u002Fp>\n\n          <sc-if value=\"{{isVallenca}}\" hint-placeholder-val=\"{{ false }}\">\n            <div style=\"display:grid;grid-template-columns:repeat(auto-fit,minmax(min(260px,100%),1fr));gap:16px\">\n              <div style=\"background:#FFFFFF;border:1px solid rgba(16,20,24,.1);border-radius:20px;padding:24px;display:flex;flex-direction:column;gap:12px\">\n                <span class=\"display\" style=\"font-weight:600;font-size:14px;color:{{modal.ink}}\">01<\u002Fspan>\n                <h4 class=\"display\" style=\"margin:0;font-weight:600;font-size:20px;color:#101418\">Konveksi<\u002Fh4>\n                <p style=\"margin:0;font-size:15px;line-height:1.6;color:#4A525C\">Layanan produksi pakaian sesuai kebutuhan pelanggan.<\u002Fp>\n              <\u002Fdiv>\n              <div style=\"background:#FFFFFF;border:1px solid rgba(16,20,24,.1);border-radius:20px;padding:24px;display:flex;flex-direction:column;gap:12px\">\n                <span class=\"display\" style=\"font-weight:600;font-size:14px;color:{{modal.ink}}\">02<\u002Fspan>\n                <h4 class=\"display\" style=\"margin:0;font-weight:600;font-size:20px;color:#101418\">Penjualan Pakaian Vallenca<\u002Fh4>\n                <p style=\"margin:0;font-size:15px;line-height:1.6;color:#4A525C\">Penjualan pakaian dengan brand Vallenca langsung kepada pelanggan.<\u002Fp>\n              <\u002Fdiv>\n            <\u002Fdiv>\n          <\u002Fsc-if>\n\n          <sc-if value=\"{{isVatech}}\" hint-placeholder-val=\"{{ false }}\">\n            <div style=\"display:grid;grid-template-columns:repeat(auto-fit,minmax(min(220px,100%),1fr));gap:16px\">\n              <div style=\"background:#FFFFFF;border:1px solid rgba(16,20,24,.1);border-radius:20px;padding:24px;display:flex;flex-direction:column;gap:12px\">\n                <span class=\"display\" style=\"font-weight:600;font-size:14px;color:{{modal.ink}}\">01<\u002Fspan>\n                <h4 class=\"display\" style=\"margin:0;font-weight:600;font-size:20px;color:#101418\">Electrical<\u002Fh4>\n                <p style=\"margin:0;font-size:15px;line-height:1.6;color:#4A525C\">Berfokus pada jasa dan layanan kelistrikan.<\u002Fp>\n              <\u002Fdiv>\n              <div style=\"background:#FFFFFF;border:1px solid rgba(16,20,24,.1);border-radius:20px;padding:24px;display:flex;flex-direction:column;gap:12px\">\n                <span class=\"display\" style=\"font-weight:600;font-size:14px;color:{{modal.ink}}\">02<\u002Fspan>\n                <h4 class=\"display\" style=\"margin:0;font-weight:600;font-size:20px;color:#101418\">Computer<\u002Fh4>\n                <p style=\"margin:0;font-size:15px;line-height:1.6;color:#4A525C\">Berfokus pada jasa bidang komputer dan teknologi pendukungnya.<\u002Fp>\n                <div style=\"display:flex;flex-wrap:wrap;gap:8px\">\n                  <span style=\"font-size:13px;font-weight:500;padding:6px 12px;border-radius:999px;background:{{modal.tint}};color:{{modal.ink}}\">IT Infrastruktur<\u002Fspan>\n                  <span style=\"font-size:13px;font-weight:500;padding:6px 12px;border-radius:999px;background:{{modal.tint}};color:{{modal.ink}}\">Jaringan<\u002Fspan>\n                  <span style=\"font-size:13px;font-weight:500;padding:6px 12px;border-radius:999px;background:{{modal.tint}};color:{{modal.ink}}\">CCTV<\u002Fspan>\n                  <span style=\"font-size:13px;font-weight:500;padding:6px 12px;border-radius:999px;background:{{modal.tint}};color:{{modal.ink}}\">IoT<\u002Fspan>\n                <\u002Fdiv>\n              <\u002Fdiv>\n              <div style=\"background:#FFFFFF;border:1px solid rgba(16,20,24,.1);border-radius:20px;padding:24px;display:flex;flex-direction:column;gap:12px\">\n                <span class=\"display\" style=\"font-weight:600;font-size:14px;color:{{modal.ink}}\">03<\u002Fspan>\n                <h4 class=\"display\" style=\"margin:0;font-weight:600;font-size:20px;color:#101418\">Software &amp; Digital<\u002Fh4>\n                <p style=\"margin:0;font-size:15px;line-height:1.6;color:#4A525C\">Berfokus pada pengembangan perangkat lunak dan layanan digital.<\u002Fp>\n                <div style=\"display:flex;flex-wrap:wrap;gap:8px\">\n                  <span style=\"font-size:13px;font-weight:500;padding:6px 12px;border-radius:999px;background:{{modal.tint}};color:{{modal.ink}}\">Development software<\u002Fspan>\n                  <span style=\"font-size:13px;font-weight:500;padding:6px 12px;border-radius:999px;background:{{modal.tint}};color:{{modal.ink}}\">Pembuatan website<\u002Fspan>\n                  <span style=\"font-size:13px;font-weight:500;padding:6px 12px;border-radius:999px;background:{{modal.tint}};color:{{modal.ink}}\">Aplikasi bisnis<\u002Fspan>\n                  <span style=\"font-size:13px;font-weight:500;padding:6px 12px;border-radius:999px;background:{{modal.tint}};color:{{modal.ink}}\">Pemasaran online<\u002Fspan>\n                <\u002Fdiv>\n              <\u002Fdiv>\n            <\u002Fdiv>\n          <\u002Fsc-if>\n\n          <sc-if value=\"{{isMooca}}\" hint-placeholder-val=\"{{ false }}\">\n            <div style=\"display:grid;grid-template-columns:repeat(auto-fit,minmax(min(260px,100%),1fr));gap:16px\">\n              <div style=\"background:#FFFFFF;border:1px solid rgba(16,20,24,.1);border-radius:20px;padding:24px;display:flex;flex-direction:column;gap:12px\">\n                <span class=\"display\" style=\"font-weight:600;font-size:14px;color:{{modal.ink}}\">01<\u002Fspan>\n                <h4 class=\"display\" style=\"margin:0;font-weight:600;font-size:20px;color:#101418\">Pengembangan Bisnis<\u002Fh4>\n                <p style=\"margin:0;font-size:15px;line-height:1.6;color:#4A525C\">Mendorong pertumbuhan dan pengembangan usaha.<\u002Fp>\n              <\u002Fdiv>\n              <div style=\"background:#FFFFFF;border:1px solid rgba(16,20,24,.1);border-radius:20px;padding:24px;display:flex;flex-direction:column;gap:12px\">\n                <span class=\"display\" style=\"font-weight:600;font-size:14px;color:{{modal.ink}}\">02<\u002Fspan>\n                <h4 class=\"display\" style=\"margin:0;font-weight:600;font-size:20px;color:#101418\">Investasi<\u002Fh4>\n                <p style=\"margin:0;font-size:15px;line-height:1.6;color:#4A525C\">Pengelolaan dan penempatan investasi untuk grup.<\u002Fp>\n              <\u002Fdiv>\n              <div style=\"background:#FFFFFF;border:1px solid rgba(16,20,24,.1);border-radius:20px;padding:24px;display:flex;flex-direction:column;gap:12px\">\n                <span class=\"display\" style=\"font-weight:600;font-size:14px;color:{{modal.ink}}\">03<\u002Fspan>\n                <h4 class=\"display\" style=\"margin:0;font-weight:600;font-size:20px;color:#101418\">Kerja Sama Usaha<\u002Fh4>\n                <p style=\"margin:0;font-size:15px;line-height:1.6;color:#4A525C\">Membuka kemitraan dan kolaborasi usaha.<\u002Fp>\n              <\u002Fdiv>\n              <div style=\"background:#FFFFFF;border:1px solid rgba(16,20,24,.1);border-radius:20px;padding:24px;display:flex;flex-direction:column;gap:12px\">\n                <span class=\"display\" style=\"font-weight:600;font-size:14px;color:{{modal.ink}}\">04<\u002Fspan>\n                <h4 class=\"display\" style=\"margin:0;font-weight:600;font-size:20px;color:#101418\">Layanan Asuransi<\u002Fh4>\n                <p style=\"margin:0;font-size:15px;line-height:1.6;color:#4A525C\">Layanan asuransi bagi seluruh grup.<\u002Fp>\n              <\u002Fdiv>\n            <\u002Fdiv>\n          <\u002Fsc-if>\n\n          <sc-if value=\"{{isLentera}}\" hint-placeholder-val=\"{{ false }}\">\n            <div style=\"display:grid;grid-template-columns:repeat(auto-fit,minmax(min(220px,100%),1fr));gap:16px\">\n              <div style=\"background:#FFFFFF;border:1px solid rgba(16,20,24,.1);border-radius:20px;padding:24px;display:flex;flex-direction:column;gap:12px\">\n                <span class=\"display\" style=\"font-weight:600;font-size:14px;color:{{modal.ink}}\">01<\u002Fspan>\n                <h4 class=\"display\" style=\"margin:0;font-weight:600;font-size:20px;color:#101418\">Penerbitan<\u002Fh4>\n                <p style=\"margin:0;font-size:15px;line-height:1.6;color:#4A525C\">Penerbitan untuk klien maupun penerbitan internal.<\u002Fp>\n                <div style=\"display:flex;flex-wrap:wrap;gap:8px\">\n                  <span style=\"font-size:13px;font-weight:500;padding:6px 12px;border-radius:999px;background:{{modal.tint}};color:{{modal.ink}}\">Buku<\u002Fspan>\n                  <span style=\"font-size:13px;font-weight:500;padding:6px 12px;border-radius:999px;background:{{modal.tint}};color:{{modal.ink}}\">Majalah<\u002Fspan>\n                  <span style=\"font-size:13px;font-weight:500;padding:6px 12px;border-radius:999px;background:{{modal.tint}};color:{{modal.ink}}\">Tabloid<\u002Fspan>\n                <\u002Fdiv>\n              <\u002Fdiv>\n              <div style=\"background:#FFFFFF;border:1px solid rgba(16,20,24,.1);border-radius:20px;padding:24px;display:flex;flex-direction:column;gap:12px\">\n                <span class=\"display\" style=\"font-weight:600;font-size:14px;color:{{modal.ink}}\">02<\u002Fspan>\n                <h4 class=\"display\" style=\"margin:0;font-weight:600;font-size:20px;color:#101418\">Publikasi Media<\u002Fh4>\n                <p style=\"margin:0;font-size:15px;line-height:1.6;color:#4A525C\">Publikasi melalui media cetak maupun online.<\u002Fp>\n                <div style=\"display:flex;flex-wrap:wrap;gap:8px\">\n                  <span style=\"font-size:13px;font-weight:500;padding:6px 12px;border-radius:999px;background:{{modal.tint}};color:{{modal.ink}}\">Cetak<\u002Fspan>\n                  <span style=\"font-size:13px;font-weight:500;padding:6px 12px;border-radius:999px;background:{{modal.tint}};color:{{modal.ink}}\">Online<\u002Fspan>\n                <\u002Fdiv>\n              <\u002Fdiv>\n              <div style=\"background:#FFFFFF;border:1px solid rgba(16,20,24,.1);border-radius:20px;padding:24px;display:flex;flex-direction:column;gap:12px\">\n                <span class=\"display\" style=\"font-weight:600;font-size:14px;color:{{modal.ink}}\">03<\u002Fspan>\n                <h4 class=\"display\" style=\"margin:0;font-weight:600;font-size:20px;color:#101418\">Kerja Sama Media<\u002Fh4>\n                <p style=\"margin:0;font-size:15px;line-height:1.6;color:#4A525C\">Kolaborasi dan kemitraan di bidang media.<\u002Fp>\n              <\u002Fdiv>\n            <\u002Fdiv>\n          <\u002Fsc-if>\n\n          <a class=\"btn\" href=\"#kontak\" sc-camel-on-click=\"{{close}}\" style=\"align-self:flex-start;display:inline-flex;align-items:center;gap:10px;min-height:48px;box-sizing:border-box;padding:12px 24px;border-radius:999px;background:#0E1217;color:#F6F4EF;font-weight:600;font-size:15px;text-decoration:none\">\n            Hubungi kami\n            <svg width=\"18\" height=\"18\" sc-camel-view-box=\"0 0 24 24\" aria-hidden=\"true\" style=\"fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round\"><path d=\"M5 12h14\"><\u002Fpath><path d=\"M12 5l7 7-7 7\"><\u002Fpath><\u002Fsvg>\n          <\u002Fa>\n        <\u002Fdiv>\n      <\u002Fdiv>\n    <\u002Fdiv>\n  <\u002Fsc-if>\n\n<\u002Fdiv>\n<sc-if data-dc-static=\"\" value=\"{{ false }}\"><style>x-dc>*{display:none!important}x-dc>[data-dc-static]{display:block!important}<\u002Fstyle>\n\n\n<div style=\"width:100%;background:#F6F4EF;color:#101418;font-family:'Inter',system-ui,sans-serif;-webkit-font-smoothing:antialiased\" data-canvas-width=\"1440\" data-canvas-height=\"3000\" data-document-role=\"page\" data-label=\"Landing Page\">\n\n  \n  <div id=\"top\" style=\"background-color:#0E1217;background-image:radial-gradient(rgba(255,255,255,.07) 1px, transparent 1px);background-size:24px 24px\">\n    <header style=\"max-width:1200px;margin:0 auto;padding:20px 24px;display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:12px 24px\">\n      <a href=\"#top\" style=\"display:flex;align-items:center;gap:12px;text-decoration:none;color:#F6F4EF\">\n        <span class=\"display\" style=\"width:40px;height:40px;border-radius:12px;background:#F2B544;display:flex;align-items:center;justify-content:center;color:#0E1217;font-weight:700;font-size:16px;flex:none\">IE<\u002Fspan>\n        <span class=\"display\" style=\"font-weight:600;font-size:18px;letter-spacing:-.01em\">Ipin Entreprise Group<\u002Fspan>\n      <\u002Fa>\n      <nav aria-label=\"Navigasi utama\" style=\"display:flex;flex-wrap:wrap;align-items:center;gap:0 28px\">\n        <a class=\"nav-link\" href=\"#tentang\" style=\"font-size:15px;padding:12px 0\">Tentang<\u002Fa>\n        <a class=\"nav-link\" href=\"#usaha\" style=\"font-size:15px;padding:12px 0\">Lini Usaha<\u002Fa>\n        <a class=\"nav-link\" href=\"#kontak\" style=\"font-size:15px;padding:12px 0\">Kontak<\u002Fa>\n      <\u002Fnav>\n    <\u002Fheader>\n\n    <section style=\"max-width:1200px;margin:0 auto;padding:56px 24px 120px;display:flex;flex-wrap:wrap;align-items:center;gap:56px\">\n      <div style=\"flex:1 1 440px;min-width:0;display:flex;flex-direction:column;gap:24px\">\n        <p style=\"margin:0;font-size:14px;letter-spacing:.16em;text-transform:uppercase;font-weight:600;color:#F2B544\">Holding Company<\u002Fp>\n        <h1 class=\"display\" style=\"margin:0;font-weight:700;font-size:clamp(44px,7vw,88px);line-height:1;letter-spacing:-.035em;color:#F6F4EF;text-wrap:balance\">Ipin Entreprise Group<\u002Fh1>\n        <p style=\"margin:0;max-width:520px;font-size:clamp(17px,2vw,20px);line-height:1.6;color:#B8BEC7;text-wrap:pretty\">Satu grup, empat lini usaha. Dari fashion, teknologi, permodalan, hingga media, tumbuh bersama dalam satu arah.<\u002Fp>\n        <div style=\"display:flex;flex-wrap:wrap;align-items:center;gap:8px 24px;margin-top:8px\">\n          <a class=\"btn\" href=\"#usaha\" style=\"display:inline-flex;align-items:center;gap:10px;min-height:52px;box-sizing:border-box;padding:14px 28px;border-radius:999px;background:#F2B544;color:#0E1217;font-weight:600;font-size:16px;text-decoration:none\">\n            Jelajahi Lini Usaha\n            <svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" aria-hidden=\"true\" style=\"fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round\"><path d=\"M5 12h14\"><\u002Fpath><path d=\"M12 5l7 7-7 7\"><\u002Fpath><\u002Fsvg>\n          <\u002Fa>\n          <a href=\"#kontak\" style=\"display:inline-flex;align-items:center;min-height:48px;padding:0 4px;color:#F6F4EF;font-weight:500;font-size:16px;text-decoration:underline;text-underline-offset:4px\">Hubungi kami<\u002Fa>\n        <\u002Fdiv>\n      <\u002Fdiv>\n\n      <div aria-hidden=\"true\" style=\"flex:0 1 400px;min-width:0;max-width:100%;padding-bottom:36px;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px\">\n        <div style=\"aspect-ratio:1/1;border-radius:28px;background:#FBE3E8;color:#9F1D3F;display:flex;align-items:center;justify-content:center\">\n          <svg width=\"56\" height=\"56\" viewBox=\"0 0 24 24\" style=\"fill:none;stroke:currentColor;stroke-width:1.6;stroke-linecap:round;stroke-linejoin:round\"><path d=\"M20.38 3.46 16 2a4 4 0 0 1-8 0L3.62 3.46a2 2 0 0 0-1.34 2.23l.58 3.47a1 1 0 0 0 .99.84H6v10c0 1.1.9 2 2 2h8a2 2 0 0 0 2-2V10h2.15a1 1 0 0 0 .99-.84l.58-3.47a2 2 0 0 0-1.34-2.23z\"><\u002Fpath><\u002Fsvg>\n        <\u002Fdiv>\n        <div style=\"aspect-ratio:1/1;border-radius:28px;background:#DCE8FB;color:#1D4ED8;display:flex;align-items:center;justify-content:center;transform:translateY(36px)\">\n          <svg width=\"56\" height=\"56\" viewBox=\"0 0 24 24\" style=\"fill:none;stroke:currentColor;stroke-width:1.6;stroke-linecap:round;stroke-linejoin:round\"><path d=\"M13 2 3 14h9l-1 8 10-12h-9l1-8z\"><\u002Fpath><\u002Fsvg>\n        <\u002Fdiv>\n        <div style=\"aspect-ratio:1/1;border-radius:28px;background:#D8F0E6;color:#0B6B4D;display:flex;align-items:center;justify-content:center\">\n          <svg width=\"56\" height=\"56\" viewBox=\"0 0 24 24\" style=\"fill:none;stroke:currentColor;stroke-width:1.6;stroke-linecap:round;stroke-linejoin:round\"><path d=\"M22 7 13.5 15.5 8.5 10.5 2 17\"><\u002Fpath><path d=\"M16 7h6v6\"><\u002Fpath><\u002Fsvg>\n        <\u002Fdiv>\n        <div style=\"aspect-ratio:1/1;border-radius:28px;background:#FBEBCB;color:#8A5200;display:flex;align-items:center;justify-content:center;transform:translateY(36px)\">\n          <svg width=\"56\" height=\"56\" viewBox=\"0 0 24 24\" style=\"fill:none;stroke:currentColor;stroke-width:1.6;stroke-linecap:round;stroke-linejoin:round\"><path d=\"M2 3h6a4 4 0 0 1 4 4v14a3 3 0 0 0-3-3H2z\"><\u002Fpath><path d=\"M22 3h-6a4 4 0 0 0-4 4v14a3 3 0 0 1 3-3h7z\"><\u002Fpath><\u002Fsvg>\n        <\u002Fdiv>\n      <\u002Fdiv>\n    <\u002Fsection>\n  <\u002Fdiv>\n\n  \n  <section id=\"tentang\" style=\"max-width:1200px;margin:0 auto;padding:104px 24px;display:flex;flex-wrap:wrap;gap:48px 80px\">\n    <div style=\"flex:1 1 380px;min-width:0;display:flex;flex-direction:column;gap:20px\">\n      <p style=\"margin:0;font-size:14px;letter-spacing:.16em;text-transform:uppercase;font-weight:600;color:#8A5200\">Tentang Kami<\u002Fp>\n      <h2 class=\"display\" style=\"margin:0;font-weight:700;font-size:clamp(30px,4vw,46px);line-height:1.1;letter-spacing:-.025em;text-wrap:balance\">Satu rumah untuk beragam usaha<\u002Fh2>\n      <p style=\"margin:0;font-size:18px;line-height:1.7;color:#3A424C;text-wrap:pretty\">Ipin Entreprise Group adalah holding company yang menaungi empat lini usaha di bidang fashion, teknik dan teknologi, permodalan, serta media. Setiap lini fokus pada keahliannya sendiri, namun saling menopang sebagai satu grup.<\u002Fp>\n    <\u002Fdiv>\n    <div style=\"flex:1 1 380px;min-width:0;display:flex;flex-direction:column\">\n      <div style=\"display:flex;gap:20px;padding:28px 0;border-top:1px solid rgba(16,20,24,.14)\">\n        <span class=\"display\" style=\"flex:none;width:32px;font-weight:600;font-size:15px;color:#8A5200\">01<\u002Fspan>\n        <div style=\"display:flex;flex-direction:column;gap:6px;min-width:0\">\n          <h3 class=\"display\" style=\"margin:0;font-weight:600;font-size:22px;letter-spacing:-.01em\">Fokus di tiap lini<\u002Fh3>\n          <p style=\"margin:0;font-size:16px;line-height:1.6;color:#4A525C\">Setiap usaha punya divisi dan keahlian sendiri, sehingga layanan lebih terarah.<\u002Fp>\n        <\u002Fdiv>\n      <\u002Fdiv>\n      <div style=\"display:flex;gap:20px;padding:28px 0;border-top:1px solid rgba(16,20,24,.14)\">\n        <span class=\"display\" style=\"flex:none;width:32px;font-weight:600;font-size:15px;color:#8A5200\">02<\u002Fspan>\n        <div style=\"display:flex;flex-direction:column;gap:6px;min-width:0\">\n          <h3 class=\"display\" style=\"margin:0;font-weight:600;font-size:22px;letter-spacing:-.01em\">Saling menopang<\u002Fh3>\n          <p style=\"margin:0;font-size:16px;line-height:1.6;color:#4A525C\">Mooca Capital mendukung pengembangan bisnis, investasi, dan asuransi bagi seluruh grup.<\u002Fp>\n        <\u002Fdiv>\n      <\u002Fdiv>\n      <div style=\"display:flex;gap:20px;padding:28px 0;border-top:1px solid rgba(16,20,24,.14);border-bottom:1px solid rgba(16,20,24,.14)\">\n        <span class=\"display\" style=\"flex:none;width:32px;font-weight:600;font-size:15px;color:#8A5200\">03<\u002Fspan>\n        <div style=\"display:flex;flex-direction:column;gap:6px;min-width:0\">\n          <h3 class=\"display\" style=\"margin:0;font-weight:600;font-size:22px;letter-spacing:-.01em\">Lintas sektor<\u002Fh3>\n          <p style=\"margin:0;font-size:16px;line-height:1.6;color:#4A525C\">Konveksi dan fashion, kelistrikan dan IT, permodalan, serta penerbitan dan media.<\u002Fp>\n        <\u002Fdiv>\n      <\u002Fdiv>\n    <\u002Fdiv>\n  <\u002Fsection>\n\n  \n  <section id=\"usaha\" style=\"background:#EDEAE1\">\n    <div style=\"max-width:1200px;margin:0 auto;padding:104px 24px;display:flex;flex-direction:column;gap:48px\">\n      <div style=\"display:flex;flex-direction:column;gap:16px;max-width:640px\">\n        <p style=\"margin:0;font-size:14px;letter-spacing:.16em;text-transform:uppercase;font-weight:600;color:#8A5200\">Lini Usaha<\u002Fp>\n        <h2 class=\"display\" style=\"margin:0;font-weight:700;font-size:clamp(30px,4vw,46px);line-height:1.1;letter-spacing:-.025em;text-wrap:balance\">Empat usaha, satu grup<\u002Fh2>\n        <p style=\"margin:0;font-size:18px;line-height:1.6;color:#3A424C\">Pilih salah satu lini untuk melihat divisi di dalamnya.<\u002Fp>\n      <\u002Fdiv>\n\n      <div style=\"display:grid;grid-template-columns:repeat(auto-fit,minmax(min(440px,100%),1fr));gap:20px\">\n\n        <button class=\"lift\" aria-haspopup=\"dialog\" style=\"text-align:left;display:flex;flex-direction:column;gap:20px;min-height:300px;box-sizing:border-box;padding:32px;background:#FFFFFF;border:1px solid rgba(16,20,24,.08);border-radius:28px;cursor:pointer;color:#101418;font:inherit\">\n          <span style=\"display:flex;align-items:center;justify-content:space-between;gap:12px\">\n            <span style=\"width:56px;height:56px;border-radius:16px;background:#FBE3E8;color:#9F1D3F;display:flex;align-items:center;justify-content:center\">\n              <svg width=\"28\" height=\"28\" viewBox=\"0 0 24 24\" aria-hidden=\"true\" style=\"fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round\"><path d=\"M20.38 3.46 16 2a4 4 0 0 1-8 0L3.62 3.46a2 2 0 0 0-1.34 2.23l.58 3.47a1 1 0 0 0 .99.84H6v10c0 1.1.9 2 2 2h8a2 2 0 0 0 2-2V10h2.15a1 1 0 0 0 .99-.84l.58-3.47a2 2 0 0 0-1.34-2.23z\"><\u002Fpath><\u002Fsvg>\n            <\u002Fspan>\n            <span style=\"font-size:13px;font-weight:600;padding:6px 12px;border-radius:999px;background:#FBE3E8;color:#9F1D3F\">2 Divisi<\u002Fspan>\n          <\u002Fspan>\n          <span class=\"display\" style=\"display:block;font-weight:600;font-size:28px;letter-spacing:-.02em\">Vallenca Lifestyle<\u002Fspan>\n          <span style=\"display:block;font-size:16px;line-height:1.6;color:#4A525C\">Konveksi dan fashion dengan brand sendiri, dari produksi pakaian hingga penjualan kepada pelanggan.<\u002Fspan>\n          <span style=\"margin-top:auto;display:flex;align-items:center;gap:8px;font-weight:600;font-size:15px;color:#9F1D3F\">\n            Lihat divisi\n            <svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" aria-hidden=\"true\" style=\"fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round\"><path d=\"M5 12h14\"><\u002Fpath><path d=\"M12 5l7 7-7 7\"><\u002Fpath><\u002Fsvg>\n          <\u002Fspan>\n        <\u002Fbutton>\n\n        <button class=\"lift\" aria-haspopup=\"dialog\" style=\"text-align:left;display:flex;flex-direction:column;gap:20px;min-height:300px;box-sizing:border-box;padding:32px;background:#FFFFFF;border:1px solid rgba(16,20,24,.08);border-radius:28px;cursor:pointer;color:#101418;font:inherit\">\n          <span style=\"display:flex;align-items:center;justify-content:space-between;gap:12px\">\n            <span style=\"width:56px;height:56px;border-radius:16px;background:#DCE8FB;color:#1D4ED8;display:flex;align-items:center;justify-content:center\">\n              <svg width=\"28\" height=\"28\" viewBox=\"0 0 24 24\" aria-hidden=\"true\" style=\"fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round\"><path d=\"M13 2 3 14h9l-1 8 10-12h-9l1-8z\"><\u002Fpath><\u002Fsvg>\n            <\u002Fspan>\n            <span style=\"font-size:13px;font-weight:600;padding:6px 12px;border-radius:999px;background:#DCE8FB;color:#1D4ED8\">3 Divisi<\u002Fspan>\n          <\u002Fspan>\n          <span class=\"display\" style=\"display:block;font-weight:600;font-size:28px;letter-spacing:-.02em\">Vatech Corpora<\u002Fspan>\n          <span style=\"display:block;font-size:16px;line-height:1.6;color:#4A525C\">Solusi kelistrikan, komputer dan infrastruktur IT, serta software dan digital dalam satu usaha.<\u002Fspan>\n          <span style=\"margin-top