n style=\"font-size:13px;font-weight:500;padding:6px 12px;border-radius:999px;background:;color:\">IT Infrastruktur<\u002Fspan>\n                  <span style=\"font-size:13px;font-weight:500;padding:6px 12px;border-radius:999px;background:;color:\">Jaringan<\u002Fspan>\n                  <span style=\"font-size:13px;font-weight:500;padding:6px 12px;border-radius:999px;background:;color:\">CCTV<\u002Fspan>\n                  <span style=\"font-size:13px;font-weight:500;padding:6px 12px;border-radius:999px;background:;color:\">IoT<\u002Fspan>\n                <\u002Fdiv>\n              <\u002Fdiv>\n              <div style=\"background:#FFFFFF;border:1px solid rgba(16,20,24,.1);border-radius:20px;padding:24px;display:flex;flex-direction:column;gap:12px\">\n                <span class=\"display\" style=\"font-weight:600;font-size:14px;color:\">03<\u002Fspan>\n                <h4 class=\"display\" style=\"margin:0;font-weight:600;font-size:20px;color:#101418\">Software &amp; Digital<\u002Fh4>\n                <p style=\"margin:0;font-size:15px;line-height:1.6;color:#4A525C\">Berfokus pada pengembangan perangkat lunak dan layanan digital.<\u002Fp>\n                <div style=\"display:flex;flex-wrap:wrap;gap:8px\">\n                  <span style=\"font-size:13px;font-weight:500;padding:6px 12px;border-radius:999px;background:;color:\">Development software<\u002Fspan>\n                  <span style=\"font-size:13px;font-weight:500;padding:6px 12px;border-radius:999px;background:;color:\">Pembuatan website<\u002Fspan>\n                  <span style=\"font-size:13px;font-weight:500;padding:6px 12px;border-radius:999px;background:;color:\">Aplikasi bisnis<\u002Fspan>\n                  <span style=\"font-size:13px;font-weight:500;padding:6px 12px;border-radius:999px;background:;color:\">Pemasaran online<\u002Fspan>\n                <\u002Fdiv>\n              <\u002Fdiv>\n            <\u002Fdiv>\n          \n\n          \n            <div style=\"display:grid;grid-template-columns:repeat(auto-fit,minmax(min(260px,100%),1fr));gap:16px\">\n              <div style=\"background:#FFFFFF;border:1px solid rgba(16,20,24,.1);border-radius:20px;padding:24px;display:flex;flex-direction:column;gap:12px\">\n                <span class=\"display\" style=\"font-weight:600;font-size:14px;color:\">01<\u002Fspan>\n                <h4 class=\"display\" style=\"margin:0;font-weight:600;font-size:20px;color:#101418\">Pengembangan Bisnis<\u002Fh4>\n                <p style=\"margin:0;font-size:15px;line-height:1.6;color:#4A525C\">Mendorong pertumbuhan dan pengembangan usaha.<\u002Fp>\n              <\u002Fdiv>\n              <div style=\"background:#FFFFFF;border:1px solid rgba(16,20,24,.1);border-radius:20px;padding:24px;display:flex;flex-direction:column;gap:12px\">\n                <span class=\"display\" style=\"font-weight:600;font-size:14px;color:\">02<\u002Fspan>\n                <h4 class=\"display\" style=\"margin:0;font-weight:600;font-size:20px;color:#101418\">Investasi<\u002Fh4>\n                <p style=\"margin:0;font-size:15px;line-height:1.6;color:#4A525C\">Pengelolaan dan penempatan investasi untuk grup.<\u002Fp>\n              <\u002Fdiv>\n              <div style=\"background:#FFFFFF;border:1px solid rgba(16,20,24,.1);border-radius:20px;padding:24px;display:flex;flex-direction:column;gap:12px\">\n                <span class=\"display\" style=\"font-weight:600;font-size:14px;color:\">03<\u002Fspan>\n                <h4 class=\"display\" style=\"margin:0;font-weight:600;font-size:20px;color:#101418\">Kerja Sama Usaha<\u002Fh4>\n                <p style=\"margin:0;font-size:15px;line-height:1.6;color:#4A525C\">Membuka kemitraan dan kolaborasi usaha.<\u002Fp>\n              <\u002Fdiv>\n              <div style=\"background:#FFFFFF;border:1px solid rgba(16,20,24,.1);border-radius:20px;padding:24px;display:flex;flex-direction:column;gap:12px\">\n                <span class=\"display\" style=\"font-weight:600;font-size:14px;color:\">04<\u002Fspan>\n                <h4 class=\"display\" style=\"margin:0;font-weight:600;font-size:20px;color:#101418\">Layanan Asuransi<\u002Fh4>\n                <p style=\"margin:0;font-size:15px;line-height:1.6;color:#4A525C\">Layanan asuransi bagi seluruh grup.<\u002Fp>\n              <\u002Fdiv>\n            <\u002Fdiv>\n          \n\n          \n            <div style=\"display:grid;grid-template-columns:repeat(auto-fit,minmax(min(220px,100%),1fr));gap:16px\">\n              <div style=\"background:#FFFFFF;border:1px solid rgba(16,20,24,.1);border-radius:20px;padding:24px;display:flex;flex-direction:column;gap:12px\">\n                <span class=\"display\" style=\"font-weight:600;font-size:14px;color:\">01<\u002Fspan>\n                <h4 class=\"display\" style=\"margin:0;font-weight:600;font-size:20px;color:#101418\">Penerbitan<\u002Fh4>\n                <p style=\"margin:0;font-size:15px;line-height:1.6;color:#4A525C\">Penerbitan untuk klien maupun penerbitan internal.<\u002Fp>\n                <div style=\"display:flex;flex-wrap:wrap;gap:8px\">\n                  <span style=\"font-size:13px;font-weight:500;padding:6px 12px;border-radius:999px;background:;color:\">Buku<\u002Fspan>\n                  <span style=\"font-size:13px;font-weight:500;padding:6px 12px;border-radius:999px;background:;color:\">Majalah<\u002Fspan>\n                  <span style=\"font-size:13px;font-weight:500;padding:6px 12px;border-radius:999px;background:;color:\">Tabloid<\u002Fspan>\n                <\u002Fdiv>\n              <\u002Fdiv>\n              <div style=\"background:#FFFFFF;border:1px solid rgba(16,20,24,.1);border-radius:20px;padding:24px;display:flex;flex-direction:column;gap:12px\">\n                <span class=\"display\" style=\"font-weight:600;font-size:14px;color:\">02<\u002Fspan>\n                <h4 class=\"display\" style=\"margin:0;font-weight:600;font-size:20px;color:#101418\">Publikasi Media<\u002Fh4>\n                <p style=\"margin:0;font-size:15px;line-height:1.6;color:#4A525C\">Publikasi melalui media cetak maupun online.<\u002Fp>\n                <div style=\"display:flex;flex-wrap:wrap;gap:8px\">\n                  <span style=\"font-size:13px;font-weight:500;padding:6px 12px;border-radius:999px;background:;color:\">Cetak<\u002Fspan>\n                  <span style=\"font-size:13px;font-weight:500;padding:6px 12px;border-radius:999px;background:;color:\">Online<\u002Fspan>\n                <\u002Fdiv>\n              <\u002Fdiv>\n              <div style=\"background:#FFFFFF;border:1px solid rgba(16,20,24,.1);border-radius:20px;padding:24px;display:flex;flex-direction:column;gap:12px\">\n                <span class=\"display\" style=\"font-weight:600;font-size:14px;color:\">03<\u002Fspan>\n                <h4 class=\"display\" style=\"margin:0;font-weight:600;font-size:20px;color:#101418\">Kerja Sama Media<\u002Fh4>\n                <p style=\"margin:0;font-size:15px;line-height:1.6;color:#4A525C\">Kolaborasi dan kemitraan di bidang media.<\u002Fp>\n              <\u002Fdiv>\n            <\u002Fdiv>\n          \n\n          <a class=\"btn\" href=\"#kontak\" style=\"align-self:flex-start;display:inline-flex;align-items:center;gap:10px;min-height:48px;box-sizing:border-box;padding:12px 24px;border-radius:999px;background:#0E1217;color:#F6F4EF;font-weight:600;font-size:15px;text-decoration:none\">\n            Hubungi kami\n            <svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" aria-hidden=\"true\" style=\"fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round\"><path d=\"M5 12h14\"><\u002Fpath><path d=\"M12 5l7 7-7 7\"><\u002Fpath><\u002Fsvg>\n          <\u002Fa>\n        <\u002Fdiv>\n      <\u002Fdiv>\n    <\u002Fdiv>\n  \n\n<\u002Fdiv>\n<\u002Fsc-if><\u002Fx-dc>\n<script type=\"text/x-dc\" data-dc-script=\"\" data-props=\"{&quot;accent&quot;:{&quot;editor&quot;:&quot;color&quot;,&quot;default&quot;:&quot;#F2B544&quot;,&quot;options&quot;:[&quot;#F2B544&quot;,&quot;#7DD3A8&quot;,&quot;#7FB2FF&quot;,&quot;#F28B82&quot;]},&quot;whatsapp&quot;:{&quot;editor&quot;:&quot;text&quot;,&quot;default&quot;:&quot;&quot;,&quot;section&quot;:&quot;Kontak&quot;},&quot;$preview&quot;:{&quot;width&quot;:1440,&quot;height&quot;:3000}}\">\nclass Component extends DCLogic {\n  constructor(props) {\n    super(props);\n    this.state = { openId: null, name: '', topic: 'Vallenca Lifestyle', message: '' };\n  }\n\n  componentDidUpdate(prevProps, prevState) {\n    var before = prevState && prevState.openId;\n    var now = this.state && this.state.openId;\n    if (now && now !== before) {\n      try {\n        var el = document.getElementById('modal-close');\n        if (el) el.focus();\n      } catch (e) {}\n    }\n  }\n\n  renderVals() {\n    var s = this.state || {};\n    var openId = s.openId || null;\n\n    var BIZ = {\n      vallenca: {\n        name: 'Vallenca Lifestyle',\n        eyebrow: 'Lini Usaha · 2 Divisi',\n        tagline: 'Konveksi dan fashion dengan brand sendiri, dari produksi pakaian hingga penjualan kepada pelanggan.',\n        listLabel: 'Divisi',\n        tint: '#FBE3E8',\n        ink: '#9F1D3F'\n      },\n      vatech: {\n        name: 'Vatech Corpora',\n        eyebrow: 'Lini Usaha · 3 Divisi',\n        tagline: 'Solusi kelistrikan, komputer dan infrastruktur IT, serta software dan digital dalam satu usaha.',\n        listLabel: 'Divisi',\n        tint: '#DCE8FB',\n        ink: '#1D4ED8'\n      },\n      mooca: {\n        name: 'Mooca Capital',\n        eyebrow: 'Lini Usaha · 4 Bidang',\n        tagline: 'Mendukung pertumbuhan grup lewat pengembangan bisnis, investasi, kerja sama usaha, dan layanan asuransi.',\n        listLabel: 'Bidang usaha',\n        tint: '#D8F0E6',\n        ink: '#0B6B4D'\n      },\n      lentera: {\n        name: 'Lentera Media',\n        eyebrow: 'Lini Usaha · 3 Divisi',\n        tagline: 'Penerbitan, publikasi media, dan kerja sama media untuk klien maupun internal grup.',\n        listLabel: 'Divisi',\n        tint: '#FBEBCB',\n        ink: '#8A5200'\n      }\n    };\n\n    var self = this;\n    var open = function (id) { return function () { self.setState({ openId: id }); }; };\n\n    // Link WhatsApp: aktif jika nomor diisi lewat Tweaks, jika tidak tombol menuju bagian kontak.\n    var digits = String(this.props.whatsapp || '').replace(/\\D/g, '');\n    var num = digits.indexOf('0') === 0 ? '62' + digits.slice(1) : digits;\n    var text = 'Halo Ipin Entreprise Group';\n    if (s.name) { text += ', saya ' + s.name; }\n    text += '. Saya tertarik dengan ' + (s.topic || 'Vallenca Lifestyle') + '.';\n    if (s.message) { text += '\\n\\n' + s.message; }\n    var waHref = num ? 'https://wa.me/' + num + '?text=' + encodeURIComponent(text) : '#kontak';\n\n    return {\n      accent: this.props.accent ?? '#F2B544',\n\n      isOpen: !!openId,\n      isVallenca: openId === 'vallenca',\n      isVatech: openId === 'vatech',\n      isMooca: openId === 'mooca',\n      isLentera: openId === 'lentera',\n      modal: BIZ[openId] || BIZ.vallenca,\n\n      openVallenca: open('vallenca'),\n      openVatech: open('vatech'),\n      openMooca: open('mooca'),\n      openLentera: open('lentera'),\n      close: function () { self.setState({ openId: null }); },\n      onKey: function (e) { if (e && e.key === 'Escape') { self.setState({ openId: null }); } },\n\n      form: { name: s.name || '', topic: s.topic || 'Vallenca Lifestyle', message: s.message || '' },\n      setName: function (e) { self.setState({ name: e.target.value }); },\n      setTopic: function (e) { self.setState({ topic: e.target.value }); },\n      setMessage: function (e) { self.setState({ message: e.target.value }); },\n\n      waDisplay: num ? '+' + num : '[NOMOR WHATSAPP]',\n      waHref: waHref,\n      waTarget: num ? '_blank' : '_self'\n    };\n  }\n}\n<\u002Fscript>\n\n\n<\u002Fbody><\u002Fhtml>"
  </script>
</body>
</html>
